mapper.update:
update it_purchase_request
applicant_id = #{applicantId}, status = #{status}, approver = #{approver}, handled_at = #{handledAt}, erp_no = #{erpNo}, ordered_at = #{orderedAt}, asset_no = #{assetNo}, handover_by = #{handoverBy}, handover_at = #{handoverAt}, remark = #{remark}, ding_instance_id = #{dingInstanceId}, ding_status = #{dingStatus}, ding_synced_at = #{dingSyncedAt}, ding_message = #{dingMessage},
where id = #{id}

mapper.select:
select r.*, a.name as assetName
from it_purchase_request r left join it_asset a on a.no = r.asset_no
where r.id = #{id}

select r.*, a.name as assetName
from it_purchase_request r left join it_asset a on a.no = r.asset_no
where r.no = #{no}
